output_text:
[
  {
    "id": "no_carts_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileAisle"
        ]
      }
    }
  },
  {
    "id": "no_cartless_broad_store_travel",
    "text": "A shopper may walk without a cart only at the entrance/cart bay, in a single-file aisle, or at the mouth of such an aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "cartBay": "at(1,7)",
        "entranceCell": "at(0,7)",
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "cartlessAllowedZone": {
          "or": [
            "entranceCell",
            "cartBay",
            "singleFileAisle",
            "singleFileMouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cartlessAllowedZone"
          }
        ]
      }
    }
  },
  {
    "id": "park_before_entering_single_file",
    "text": "Before entering a single-file shelf aisle, the shopper must not still be pushing the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "MOVE",
              "hasCart"
            ]
          },
          "post": "singleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "retrieve_cart_after_single_file",
    "text": "After returning from a single-file aisle to its mouth without a cart, the shopper is obliged to retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "exitSingleFileToMouthWithoutCart": {
          "pre": {
            "and": [
              "singleFileAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileMouth"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileToMouthWithoutCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "broad_shelf_interact_requires_cart",
    "text": "Interacting with a shelf from a broad aisle requires having the cart with you.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "broadShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "broadShelfFace",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "do_not_push_into_north_shelf_choke",
    "text": "At a narrow cart service bay with a shelf immediately to the north, the cart must not be pushed north toward the shelf.",
    "abstraction": {
      "state_properties": {
        "northShelfChokeBay": {
          "and": [
            "hasCart",
            "shelfN",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "northShelfChokeBay",
          "N"
        ]
      }
    }
  },
  {
    "id": "main_exit_lane_one_way_east",
    "text": "The bottom exit lane is one-way for carts, so shoppers with carts should not travel west along it.",
    "abstraction": {
      "state_properties": {
        "bottomExitLane": {
          "or": [
            "at(0,7)",
            "at(1,7)",
            "at(2,7)",
            "at(3,7)",
            "at(4,7)",
            "at(5,7)",
            "at(6,7)",
            "at(7,7)",
            "at(8,7)",
            "at(9,7)",
            "at(10,7)",
            "at(11,7)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "bottomExitLane",
          "W"
        ]
      }
    }
  },
  {
    "id": "right_perimeter_exit_only",
    "text": "Once a shopper with a cart reaches the right perimeter aisle, they should continue toward the exit rather than re-entering the store.",
    "abstraction": {
      "state_properties": {
        "rightPerimeterAisle": {
          "or": [
            "at(11,4)",
            "at(11,5)",
            "at(11,6)",
            "at(11,7)"
          ]
        },
        "notAtExitCell": {
          "not": "at(11,7)"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "rightPerimeterAisle",
          "notAtExitCell",
          {
            "not": "S"
          }
        ]
      }
    }
  }
]
